    def create_container_registry_namespace(self, credential_id, registry_id, timeout=60, **kwargs):
        return self.inventory_manager.create_container_registry_namespace(credential_id=credential_id,
                                                                           registry_id=registry_id,
                                                                           timeout=timeout, **kwargs)

